// HasWorkspace applies the HasEdge predicate on the "workspace" edge.
func HasWorkspace() predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkspaceTable, WorkspaceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkspaceWith applies the HasEdge predicate on the "workspace" edge with a given conditions (other predicates).
func HasWorkspaceWith(preds ...predicate.RevenueWorkspace) predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(func(s *sql.Selector) {
		step := newWorkspaceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasInteraction applies the HasEdge predicate on the "interaction" edge.
func HasInteraction() predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, InteractionTable, InteractionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasInteractionWith applies the HasEdge predicate on the "interaction" edge with a given conditions (other predicates).
func HasInteractionWith(preds ...predicate.CommunicationInteraction) predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(func(s *sql.Selector) {
		step := newInteractionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CommunicationAttachment) predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CommunicationAttachment) predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CommunicationAttachment) predicate.CommunicationAttachment {
	return predicate.CommunicationAttachment(sql.NotPredicates(p))
}
